async function gGet(fallback) {
  return sGet("gc-game", fallback);
}
async function gSet(value) {
  return sSet("gc-game", value);
}
/** Only writes if the shared game state's phase still matches expectedPhase (best-effort race guard). */
async function gAdvance(expectedPhase, updater) {
  const current = await gGet(IDLE_GAME);
  if (current.phase !== expectedPhase) return current;
  const next = updater(current);
  await gSet(next);
  return next;
}
const IDLE_GAME = { type: null, phase: "idle" };

function useNow(tickMs = 1000) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const iv = setInterval(() => setNow(Date.now()), tickMs);
    return () => clearInterval(iv);
  }, [tickMs]);
  return now;
}

function TimerBar({ startedAt, durationSeconds, label }) {
  const now = useNow(500);
  const left = Math.max(0, durationSeconds - Math.floor((now - startedAt) / 1000));
  const pct = Math.max(0, Math.min(100, (left / durationSeconds) * 100));
  return (
    <div className="timer-wrap">
      {label && <span className="eyebrow">{label}</span>}
      <div className="timer-track">
        <div className="timer-fill" style={{ width: `${pct}%` }} />
      </div>
      <span className="timer-num">{left}s</span>
    </div>
  );
}

/* ============ small storage helpers (best-effort, shared) ============ */
async function sGet(key, fallback) {
  try {
    const res = await fetch(`/api/storage?key=${encodeURIComponent(key)}`);
    const data = await res.json();
    return data.value !== null && data.value !== undefined ? JSON.parse(data.value) : fallback;
  } catch (e) {
    return fallback;
  }
}
async function sSet(key, value) {
  try {
    await fetch(`/api/storage?key=${encodeURIComponent(key)}`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ value: JSON.stringify(value) }),
    });
  } catch (e) {
    /* ignore */
  }
}

/* ============ Marquee bulb border ============ */
function MarqueeBulbs({ count = 18 }) {
  return (
    <div className="bulb-row" aria-hidden="true">
      {Array.from({ length: count }).map((_, i) => (
        <span key={i} className="bulb" style={{ animationDelay: `${(i % 6) * 0.18}s` }} />
      ))}
    </div>
  );
}

function FilmSprockets() {
  return (
    <div className="sprockets" aria-hidden="true">
      {Array.from({ length: 9 }).map((_, i) => (
        <span key={i} className="sprocket" />
      ))}
    </div>
  );
}

/* ============ Avatar ============ */
function Avatar({ src, name, size = 44, ring }) {
  const initials = (name || "?")
    .split(" ")
    .map((s) => s[0])
    .join("")
    .slice(0, 2)
    .toUpperCase();
  return (
    <div
      className="avatar"
      style={{
        width: size,
        height: size,
        boxShadow: ring ? "0 0 0 2px #17140f, 0 0 0 4px #C9A24B" : "0 0 0 2px rgba(23,20,15,0.15)",
      }}
      title={name}
    >
      {src ? (
        <img src={src} alt={name} />
      ) : (
        <span style={{ fontFamily: "'Bebas Neue', sans-serif", fontSize: size * 0.4 }}>{initials}</span>
      )}
    </div>
  );
}

/* ============ Avatar Picker Modal ============ */
function AvatarPicker({ onPick, onClose, current }) {
  const fileRef = useRef(null);
  const [customUpload, setCustomUpload] = useState(null);

  const handleFile = (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => setCustomUpload(reader.result);
    reader.readAsDataURL(file);
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal ticket" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <span className="eyebrow">choose your still</span>
          <button className="x-btn" onClick={onClose}>✕</button>
        </div>
        <div className="avatar-grid">
          {customUpload && (
            <button
              className={`avatar-opt ${current === customUpload ? "sel" : ""}`}
              onClick={() => onPick(customUpload)}
            >
              <img src={customUpload} alt="your upload" />
            </button>
          )}
          {PHOTO_LIST.map((src, i) => (
            <button
              key={i}
              className={`avatar-opt ${current === src ? "sel" : ""}`}
              onClick={() => onPick(src)}
            >
              <img src={src} alt={`gang cobra ${i}`} />
            </button>
          ))}
        </div>
        <button className="btn-ghost small" onClick={() => fileRef.current?.click()}>
          upload your own
        </button>
        <input ref={fileRef} type="file" accept="image/*" hidden onChange={handleFile} />
      </div>
    </div>
  );
}

